fn solve(n: i8, m: i8) -> (i8, i8) {
    // The second component is the smaller of n and m.
    let second = n.min(m);
    // The first component is (larger of n and m) minus 1.
    // This computation cannot overflow i8 because:
    //   - larger ∈ [1, 127]
    //   - so larger - 1 ∈ [0, 126]
    let first = n.max(m) - 1;
    (first, second)
}

