        assert_eq!(solve(5, 3), (4, 3));     // 5+3-1 = 7  => (4,3)
        assert_eq!(solve(3, 5), (4, 3));     // symmetric
        assert_eq!(solve(127, 1), (126, 1)); // edge values
        assert_eq!(solve(1, 127), (126, 1));
        assert_eq!(solve(127, 127), (126, 127));
